<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import type { BitacoraFiltros, BitacoraFinanzas, ValorAuditoria } from '../interfaces/bitacora.interface'
import { listarBitacora, obtenerBitacora } from '../services/bitacora'
const blank=():BitacoraFiltros=>({entidad:'',accion_id:'',tabla:'',user_id:'',fecha_desde:'',fecha_hasta:'',buscar:''})
const filters=reactive(blank()),rows=ref<BitacoraFinanzas[]>([]),entities=ref<Record<string,string>>({}),actions=ref<Record<string,string>>({}),tables=ref<string[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),detail=ref<BitacoraFinanzas|null>(null),error=ref('')
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo cargar la bitácora.',date=(v:string)=>new Date(v).toLocaleString('es-PE'),entries=(v?:Record<string,ValorAuditoria>)=>Object.entries(v||{}),display=(v:ValorAuditoria)=>typeof v==='object'&&v!==null?JSON.stringify(v,null,2):v===null||v===''?'(vacío)':typeof v==='boolean'?(v?'Sí':'No'):String(v)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarBitacora(filters,next);rows.value=r.data;entities.value=r.entidades;actions.value=r.acciones;tables.value=r.tablas;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function open(item:BitacoraFinanzas){loading.value=true;error.value='';try{detail.value=await obtenerBitacora(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blank());load(1)}
const badge=(a:string)=>{const v=a.toUpperCase();return v.includes('ELIM')||v.includes('ANUL')?'bad':v.includes('CRE')||v.includes('ACTIV')||v.includes('APROB')?'good':'warn'}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Bitácora</nav><header class="hero"><div class="mark">BF</div><div><small>MIA · FINANZAS · AUDITORÍA</small><h1>Bitácora de Finanzas</h1><p>Trazabilidad de cambios realizados en los procesos financieros.</p></div><strong>{{total}} eventos</strong></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="filters.buscar" class="wide" placeholder="Tabla, entidad, registro, descripción, IP o usuario"><select v-model="filters.entidad"><option value="">Todas las entidades</option><option v-for="(name,key) in entities" :key="key" :value="key">{{name}}</option></select><select v-model="filters.accion_id"><option value="">Todas las acciones</option><option v-for="(name,key) in actions" :key="key" :value="key">{{name}}</option></select><select v-model="filters.tabla"><option value="">Todas las tablas</option><option v-for="table in tables" :key="table">{{table}}</option></select><input v-model="filters.user_id" type="number" placeholder="ID usuario"><input v-model="filters.fecha_desde" type="date"><input v-model="filters.fecha_hasta" type="date"><div><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></div></form><section class="card"><div v-if="loading&&!detail" class="empty">Consultando bitácora…</div><div v-else-if="!rows.length" class="empty">No existen registros para los filtros seleccionados.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Fecha y hora</th><th>Acción</th><th>Entidad / tabla</th><th>Registro</th><th>Usuario</th><th>IP</th><th></th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td>{{date(item.fecha)}}</td><td><span :class="badge(item.accion)">{{item.accion_formateada||item.accion}}</span></td><td><b>{{item.modelo_nombre||item.entidad}}</b><small>{{item.tabla}}</small></td><td><b>{{item.descripcion||'Sin descripción'}}</b><small v-if="item.registro_id">ID: {{item.registro_id}}</small></td><td>{{item.usuario_nombre||'Sistema'}}<small>{{item.usuario_email}}</small></td><td>{{item.ip_origen||'N/A'}}</td><td><button @click="open(item)">Ver detalle</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>EVENTO #{{detail.id}}</small><h2>{{detail.accion_formateada||detail.accion}}</h2></div><button @click="detail=null">×</button></header><div class="facts"><div><small>FECHA</small><b>{{date(detail.fecha)}}</b></div><div><small>ENTIDAD</small><b>{{detail.modelo_nombre||detail.entidad}}</b></div><div><small>TABLA / REGISTRO</small><b>{{detail.tabla}} · {{detail.registro_id||'N/D'}}</b></div><div><small>USUARIO / IP</small><b>{{detail.usuario_nombre||'Sistema'}} · {{detail.ip_origen||'N/A'}}</b></div></div><p>{{detail.descripcion||'Sin descripción adicional.'}}</p><div v-if="entries(detail.valor_anterior).length||entries(detail.valor_nuevo).length" class="change"><table><thead><tr><th>Campo</th><th>Valor anterior</th><th>Valor nuevo</th></tr></thead><tbody><tr v-for="key in [...new Set([...entries(detail.valor_anterior).map(x=>x[0]),...entries(detail.valor_nuevo).map(x=>x[0])])]" :key="key"><td><b>{{key.replaceAll('_',' ')}}</b></td><td><pre>{{display(detail.valor_anterior?.[key]??null)}}</pre></td><td><pre>{{display(detail.valor_nuevo?.[key]??null)}}</pre></td></tr></tbody></table></div><details><summary>Información técnica</summary><pre>{{JSON.stringify(detail.cambios,null,2)}}</pre></details></section></div></div></template>
<style scoped>
