log h2{margin:2px 0 12px}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.facts{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.facts div{display:grid;gap:4px;padding:10px;background:#f3f7f8}.dialog p{font-size:.58rem}.change{overflow:auto}.change table{min-width:700px}.change pre,details pre{margin:0;white-space:pre-wrap;font:inherit}details{margin-top:13px;padding:10px;background:#f5f7f8;font-size:.5rem}summary{cursor:pointer;font-weight:700}@media(max-width:1100px){.filters{grid-template-columns:repeat(4,1fr)}.wide{grid-column:span 2}}@media(max-width:650px){.filters,.facts{grid-template-columns:1fr}.wide{grid-column:auto}.hero{flex-wrap:wrap}}
</style>
